"""An internal bend made of tiny cubics retains its outer wedge."""
from unitgen import Unit

# Chromium reference; resvg and librsvg agree on the wedge.
REFERENCE = ''
PATH_D = 'M102.18748000,361.85415000 c-0.24215,0.21909 -0.44278,0.40784 -0.6075,0.56851c-0.24836,0.24225 -0.337,0.33432 -0.40933,0.40668c-0.05633,0.05634 -0.09867,0.09866 -0.12901,0.129c-0.02033,0.02032 -0.03265,0.03265 -0.03899,0.039c-0.00266,0.00266 -0.00267,0.00266 -0.00267,0.00266c0,0 0.00066,0 0.00533,0c0.01266,0 0.03733,0 0.078,0c0.06066,0 0.14533,0 0.258,0c0.32533,0 0.5472,0.00162 0.82,-0.004c0.3349,-0.0069 0.74292,-0.0242 1.2345,-0.0585'

unit = Unit("stroke-degenerate-internal-bend", 256, 160,
            "A run of tiny cubics nearly stops and changes heading at an internal point. "
            "Its thick stroke keeps the outer wedge, as Chromium, resvg and librsvg draw it.",
            root='viewBox="55 330 125 78.125"', ground=False)
unit.common('<rect x="55" y="330" width="125" height="78.125" fill="white"/>')
unit.cell("internal-bend", (0, 0, 256, 160),
          f'<path d="{PATH_D}" fill="none" stroke="black" stroke-width="32.08"/>',
          f'<image x="55" y="330" width="125" height="78.125" href="data:image/png;base64,{REFERENCE}"/>',
          tolerance=64)
unit.write()
